"use strict";(()=>{const data=window.LEARNWITHUS_SPORTS||[],grid=document.getElementById('sportsGrid'),search=document.getElementById('sportsSearch');if(!grid)return;const speak=t=>{if(!('speechSynthesis'in window))return;speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.lang='en-IN';u.rate=.76;speechSynthesis.speak(u)};function render(q=''){const needle=q.trim().toLowerCase();grid.innerHTML='';data.filter(s=>!needle||[s.name,s.equipment,s.players,s.goal].join(' ').toLowerCase().includes(needle)).forEach(s=>{const a=document.createElement('article');a.className='sport-card';a.innerHTML='<img src="'+s.image+'" alt="'+s.name+' illustration"><div class="sport-copy"><h2>'+s.emoji+' '+s.name+'</h2><div class="sport-facts"><div class="sport-fact"><strong>Equipment:</strong> '+s.equipment+'</div><div class="sport-fact"><strong>Players:</strong> '+s.players+'</div><div class="sport-fact"><strong>Goal:</strong> '+s.goal+'</div></div><div class="sport-actions"><button type="button">🔊 Hear facts</button></div></div>';a.querySelector('button').onclick=()=>speak(s.name+'. Equipment: '+s.equipment+'. Players: '+s.players+'. Goal: '+s.goal+'.');grid.append(a)})}search?.addEventListener('input',()=>render(search.value));render();window.LearnWithUs?.recordComplete?.('sports.html')})();